NON_LOCAL_COUNTRY_CLUSTERS = {"Казахстан", "Беларусь", "Армения"}

def validate_regions_for_ui() -> list[str]:
    warnings = []
    # Empty names
    empties = [r for r in REGION_TO_CLUSTER.keys() if not (r or "").strip()]
    if empties:
        warnings.append(f"Пустые имена регионов: {empties}")
    # Cross-cluster duplicates
    seen = {}
    conflicts = []
    for cluster, regions in CLUSTER_TO_REGIONS.items():
        for r in regions:
            prev = seen.get(r)
            if prev and prev != cluster:
                conflicts.append((r, prev, cluster))
            else:
                seen[r] = cluster
    if conflicts:
        sample = ", ".join([f"{r} ({c1} vs {c2})" for r, c1, c2 in conflicts[:10]])
        warnings.append(f"Пересечения регионов между кластерами: {sample}")
    return warnings
